import Libdl
import Diversinet_jll
import boost_jll

const package_root = normpath(joinpath(@__DIR__, ".."))
const deps_file = joinpath(@__DIR__, "deps.jl")
const bridge_source_dir = joinpath(package_root, "cpp")
const bridge_build_dir = joinpath(@__DIR__, "build-julia-interface")
const libname = "libjlDiversinetInterface." * Libdl.dlext
const core_libname = "libdiversinet." * Libdl.dlext

function require_env_path(name)
    value = get(ENV, name, "")
    isempty(value) && error("Diversinet native build requires $name to be set.")
    return abspath(expanduser(value))
end

function meson_executable()
    return get(ENV, "MESON", "meson")
end

function julia_executable()
    return get(ENV, "JULIA", joinpath(Sys.BINDIR, Base.julia_exename()))
end

function local_core_root()
    root = abspath(expanduser(get(ENV, "DIVERSINET_CPP_ROOT", "")))
    isdir(root) || error("DIVERSINET_CPP_ROOT does not exist or is not a directory: $root")
    return root
end

function local_core_library(root)
    env_lib = get(ENV, "DIVERSINET_CORE_LIB", "")
    candidates = String[]

    if !isempty(env_lib)
        push!(candidates, abspath(expanduser(env_lib)))
    end

    push!(candidates, joinpath(root, "builddir", "src", core_libname))

    for path in candidates
        if isfile(path)
            return normpath(path)
        end
    end

    error("""
    Could not find the core Diversinet library.

    Build phyloploid_lib first:

      cd $root
      meson setup builddir .
      meson compile -C builddir

    Or set:

      DIVERSINET_CORE_LIB=/path/to/$(core_libname)

    Searched:
    $(join(candidates, "\n"))
    """)
end

function jll_core()
    return (
        root = Diversinet_jll.artifact_dir,
        lib = Diversinet_jll.libdiversinet,
        include_dirs = [
            joinpath(Diversinet_jll.artifact_dir, "include"),
            joinpath(boost_jll.artifact_dir, "include"),
        ],
        use_jll = true,
    )
end

function core_config()
    env_root = get(ENV, "DIVERSINET_CPP_ROOT", "")

    if !isempty(env_root)
        root = local_core_root()
        return (
            root = root,
            lib = local_core_library(root),
            include_dirs = [
                joinpath(root, "api"),
                joinpath(root, "src"),
                joinpath(boost_jll.artifact_dir, "include"),
            ],
            use_jll = false,
        )
    end

    env_lib = get(ENV, "DIVERSINET_CORE_LIB", "")
    config = jll_core()
    if !isempty(env_lib)
        lib = abspath(expanduser(env_lib))
        isfile(lib) || error("DIVERSINET_CORE_LIB does not exist or is not a file: $lib")
        return (; config.root, lib, config.include_dirs, config.use_jll)
    end

    return config
end

function run_meson_setup(config)
    args = [
        "setup",
        bridge_build_dir,
        bridge_source_dir,
        "-Dcore_root=$(config.root)",
        "-Dcore_lib=$(config.lib)",
        "-Dcore_include_dirs=$(join(config.include_dirs, ':'))",
        "-Djulia=$(julia_executable())",
        "-Djulia_project=$package_root",
    ]

    if isfile(joinpath(bridge_build_dir, "build.ninja"))
        insert!(args, 2, "--reconfigure")
    elseif isdir(bridge_build_dir)
        insert!(args, 2, "--wipe")
    end

    run(`$(meson_executable()) $args`)
end

function build_interface_library()
    config = core_config()

    run_meson_setup(config)
    run(`$(meson_executable()) compile -C $bridge_build_dir`)

    interface_lib = joinpath(bridge_build_dir, libname)
    isfile(interface_lib) || error("Expected Meson to build $interface_lib, but it was not found.")
    return normpath(interface_lib), config
end

interface_lib, config = build_interface_library()

open(deps_file, "w") do io
    println(io, "# This file is generated by deps/build.jl.")
    println(io, "const diversinet_interface_lib = ", repr(interface_lib))
    println(io, "const diversinet_interface_uses_jll = ", repr(config.use_jll))
end

println("Configured Diversinet native interface:")
println("  ", interface_lib)
println("Using Diversinet core library:")
println("  ", config.lib)
